 		u32 value = readl(ioaddr + XGMAC_PACKET_FILTER);

 		value |= XGMAC_FILTER_VTFE;

 		writel(value, ioaddr + XGMAC_PACKET_FILTER);

 		value = readl(ioaddr + XGMAC_VLAN_TAG);

