 		value |= XGMAC_VLAN_ETV;
 		if (is_double) {
 			value |= XGMAC_VLAN_EDVLP;
 			value |= XGMAC_VLAN_ESVL;
 			value |= XGMAC_VLAN_DOVLTC;
 		} else {
 			value &= ~XGMAC_VLAN_EDVLP;
 			value &= ~XGMAC_VLAN_ESVL;
 			value &= ~XGMAC_VLAN_DOVLTC;
 		}

